{"file_path":"src/election.js","content":"/**
 * Runs an instant-runoff count over a parsed election and returns every
 * round's tallies together with the eventual winner, if any.
 */

function tieBreakEliminate(tied, history, roundCount) {
  let candidates = tied
  while (candidates.length > 1) {
    let narrowed = false
    for (let r = 0; r < roundCount; r++) {
      const votes = history[r]
      const values = candidates.map((name) => votes.get(name))
      const allEqual = values.every((v) => v === values[0])
      if (!allEqual) {
        const min = values.reduce((a, b) => (b < a ? b : a))
        candidates = candidates.filter((name) => votes.get(name) === min)
        narrowed = true
        break
      }
    }
    if (!narrowed) {
      const sorted = [...candidates].sort()
      return sorted[sorted.length - 1]
    }
  }
  return candidates[0]
}

export function runElection(candidateNames, ballots) {
  let continuing = new Set(candidateNames)
  const history = []
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0n)
    let exhausted = 0n

    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    let activeTotal = 0n
    for (const v of votes.values()) activeTotal += v

    history.push(votes)

    const sortedEntries = [...votes.entries()].sort((a, b) => {
      if (a[1] !== b[1]) return a[1] > b[1] ? -1 : 1
      return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
    })

    let eliminated = null

    if (activeTotal === 0n) {
      rounds.push({ entries: sortedEntries, exhausted, eliminated })
      break
    }

    for (const [name, count] of votes) {
      if (count * 2n > activeTotal) {
        winner = name
        break
      }
    }

    if (winner !== null) {
      rounds.push({ entries: sortedEntries, exhausted, eliminated })
      break
    }

    let min = null
    for (const v of votes.values()) {
      if (min === null || v < min) min = v
    }
    const tied = [...votes.keys()].filter((name) => votes.get(name) === min)
    eliminated = tied.length === 1 ? tied[0] : tieBreakEliminate(tied, history, history.length)

    rounds.push({ entries: sortedEntries, exhausted, eliminated })

    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
}
"}

