{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parser.js'
import { runElection } from './election.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require_fs()
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function require_fs() {
  // Lazily imported to keep the top of the file focused on the CLI flow.
  return globalThis.__fs ?? (globalThis.__fs = require('node:fs'))
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const { rounds, winner } = runElection(election.candidateNames, election.ballots)

  const output = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      const parts = round.entries.map(([name, count]) => `${name}=${count}`)
      parts.push(`exhausted=${round.exhausted}`)
      output.push(`round ${index + 1}: ${parts.join(' ')}`)
      if (round.eliminated !== null) {
        output.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    output.push(`rounds ${rounds.length}`)
  }
  output.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(output.join('\n') + '\n')
}

main()
"}

